/* From Uiverse.io by coding-masala - Tags: switch */
.__UIV_SCOPE__ .toggle-switcher {
  width: 50px;
  height: 25px;
  position: relative;
  margin: 20px auto;
  background: #000;
  border-radius: 50px;
}

.__UIV_SCOPE__ .toggle-input {
  display: none;
}

.__UIV_SCOPE__ .toggle-label {
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  border-radius: 50px;
  cursor: pointer;
  box-shadow: 0 0 0 0 #ff0000;
}

.__UIV_SCOPE__ .toggle-label::before {
  content: "";
  width: 25px;
  height: 25px;
  position: absolute;
  top: 0;
  left: 0;
  background: #ffffff;
  border-radius: 50%;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle-label {
  animation: shadow-animation_5020 10s linear infinite;
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle-label::before {
  transform: translateX(25px);
}

@keyframes shadow-animation_5020 {
  0% {
    box-shadow: 0 0 0 0 #ff0000;
  }

  50% {
    box-shadow: 0 0 25px 25px #ffa500;
  }

  100% {
    box-shadow: 0 0 0 0 #ff0000;
  }
}
